"""
音频捕获 —— WASAPI Loopback 系统音频采集。

捕获电脑正在播放的声音（16kHz, mono, 16bit PCM），通过线程安全队列输出。
"""

import threading
import queue
import logging
from typing import Optional

import numpy as np
import sounddevice as sd

from .config import get_config

logger = logging.getLogger(__name__)


class AudioCapture:
    """系统音频采集器（WASAPI Loopback）"""

    def __init__(self):
        cfg = get_config()
        self.sample_rate = cfg.sample_rate
        self.block_size = int(self.sample_rate * 0.1)  # 100ms 块
        self.queue: queue.Queue[Optional[np.ndarray]] = queue.Queue()
        self._stream: Optional[sd.InputStream] = None
        self._running = False
        self._thread: Optional[threading.Thread] = None

    def _find_loopback_device(self) -> Optional[int]:
        """查找 WASAPI Loopback 设备"""
        try:
            devices = sd.query_devices()
            for i, d in enumerate(devices):
                if d["max_input_channels"] > 0:
                    name = d["name"].lower()
                    if "loopback" in name:
                        logger.info("找到 Loopback 设备: [%d] %s", i, d["name"])
                        return int(i)
            # 备选: 查找 WASAPI 输入设备
            hostapis = sd.query_hostapis()
            for i, d in enumerate(devices):
                if d["max_input_channels"] > 0:
                    api = hostapis[d["hostapi"]]
                    if "wasapi" in api["name"].lower():
                        logger.info("使用 WASAPI 输入设备: [%d] %s", i, d["name"])
                        return int(i)
        except Exception:
            pass
        return None

    def _audio_callback(self, indata: np.ndarray, frames: int, time_info, status):
        """sounddevice 回调：每 100ms 调用一次"""
        if status:
            logger.warning("音频回调状态: %s", status)
        # 确保单声道、float32
        if indata.ndim > 1:
            indata = indata.mean(axis=1)
        self.queue.put(indata.copy())

    def start(self) -> bool:
        """启动音频捕获"""
        if self._running:
            return True

        device = self._find_loopback_device()
        if device is None:
            logger.error("未找到可用的音频输入设备。")
            logger.error("请确认：")
            logger.error("  1. 系统音频设备已启用（非静音）")
            logger.error("  2. Windows 音频服务正在运行")
            logger.error("  3. 已安装声卡驱动")
            return False

        try:
            self._stream = sd.InputStream(
                device=device,
                channels=1,
                samplerate=self.sample_rate,
                callback=self._audio_callback,
                blocksize=self.block_size,
                dtype="float32",
            )
            self._stream.start()
            self._running = True
            logger.info("音频采集已启动 (device=%d, sr=%d)", device, self.sample_rate)
            return True
        except Exception as e:
            logger.error("启动音频流失败: %s", e)
            # 尝试使用默认设备作为最后手段
            try:
                logger.warning("回退到默认输入设备...")
                self._stream = sd.InputStream(
                    channels=1,
                    samplerate=self.sample_rate,
                    callback=self._audio_callback,
                    blocksize=self.block_size,
                    dtype="float32",
                )
                self._stream.start()
                self._running = True
                logger.info("已回退到默认设备")
                return True
            except Exception as e2:
                logger.error("回退也失败: %s", e2)
                return False

    def stop(self):
        """停止音频捕获"""
        self._running = False
        if self._stream:
            try:
                self._stream.stop()
                self._stream.close()
            except Exception:
                pass
            self._stream = None
        self.queue.put(None)  # 发送停止信号
        logger.info("音频采集已停止")

    def read(self, timeout: float = 0.5) -> Optional[np.ndarray]:
        """读取一个音频块（阻塞）"""
        try:
            return self.queue.get(timeout=timeout)
        except queue.Empty:
            return None

    def read_nonblocking(self) -> Optional[np.ndarray]:
        """读取一个音频块（非阻塞）"""
        try:
            return self.queue.get_nowait()
        except queue.Empty:
            return None

"""
MiMo ASR 客户端 —— 语音识别接口。

MiMo 平台使用兼容 OpenAI 的 API 格式。
将 PCM 音频发送到 MiMo ASR 服务，返回识别的文本。
"""

import base64
import logging
from typing import Optional

import httpx

from .config import get_config

logger = logging.getLogger(__name__)


class MiMoASR:
    """MiMo 语音识别客户端"""

    def __init__(self):
        cfg = get_config()
        self.api_key = cfg.asr.api_key
        self.base_url = cfg.asr.base_url.rstrip("/")
        self.model = cfg.asr.model
        self.language = cfg.asr.language
        self._client: Optional[httpx.Client] = None

    @property
    def client(self) -> httpx.Client:
        if self._client is None:
            self._client = httpx.Client(
                base_url=self.base_url,
                headers={
                    "Authorization": f"Bearer {self.api_key}",
                    "Content-Type": "application/json",
                },
                timeout=30.0,
            )
        return self._client

    def transcribe(self, audio_pcm: bytes) -> Optional[str]:
        """
        将 PCM 音频发送到 MiMo ASR 进行识别。

        :param audio_pcm: 16kHz, mono, 16bit PCM 音频数据
        :return: 识别的文本，失败返回 None
        """
        if not audio_pcm:
            return None

        # base64 编码音频数据
        audio_b64 = base64.b64encode(audio_pcm).decode("ascii")
        data_url = f"data:audio/pcm;base64,{audio_b64}"

        # 构造 MiMo Speech Recognition 请求体
        # MiMo 使用兼容 OpenAI 的扩展格式
        body: dict = {
            "model": self.model,
            "input_audio": {
                "data": data_url,
                "format": "pcm",
                "sample_rate": 16000,
            },
            "asr_options": {
                "language": self.language,
            },
        }

        try:
            resp = self.client.post("/audio/speech", json=body)
            resp.raise_for_status()
            data = resp.json()
            text = data.get("text", "")
            if text:
                logger.info("ASR 识别结果: %s", text)
                return text.strip()
            logger.warning("ASR 返回空文本")
            return None
        except httpx.HTTPStatusError as e:
            logger.error("ASR HTTP 错误 %d: %s", e.response.status_code, e.response.text[:200])
            return None
        except Exception as e:
            logger.error("ASR 请求异常: %s", e)
            return None

    def close(self):
        if self._client:
            self._client.close()
            self._client = None

"""
MiMo ASR 客户端 —— 语音识别接口。

MiMo-V2.5-ASR 使用 OpenAI 兼容的 /v1/chat/completions 端点。
支持流式和非流式输出。音频输入仅支持 WAV 和 MP3 格式。
"""

import base64
import io
import logging
import struct
import wave
from typing import Optional

import httpx

from .config import get_config

logger = logging.getLogger(__name__)


def pcm_to_wav(pcm_data: bytes, sample_rate: int = 16000, channels: int = 1, bits: int = 16) -> bytes:
    """将原始 PCM 数据封装为 WAV 格式"""
    buf = io.BytesIO()
    with wave.open(buf, "wb") as wf:
        wf.setnchannels(channels)
        wf.setsampwidth(bits // 8)
        wf.setframerate(sample_rate)
        wf.writeframes(pcm_data)
    return buf.getvalue()


class MiMoASR:
    """MiMo 语音识别客户端"""

    def __init__(self):
        cfg = get_config()
        self.api_key = cfg.asr.api_key
        self.base_url = cfg.asr.base_url.rstrip("/")
        self.model = cfg.asr.model
        self.language = cfg.asr.language
        self._client: Optional[httpx.Client] = None

    @property
    def client(self) -> httpx.Client:
        if self._client is None:
            self._client = httpx.Client(
                base_url=self.base_url,
                headers={
                    "api-key": self.api_key,
                    "Content-Type": "application/json",
                },
                timeout=30.0,
            )
        return self._client

    def transcribe(self, audio_pcm: bytes) -> Optional[str]:
        """
        将 PCM 音频发送到 MiMo ASR 进行识别。

        :param audio_pcm: 16kHz, mono, 16bit PCM 音频数据
        :return: 识别的文本，失败返回 None
        """
        if not audio_pcm:
            return None

        # PCM → WAV 封装
        wav_data = pcm_to_wav(audio_pcm, sample_rate=16000)
        audio_b64 = base64.b64encode(wav_data).decode("ascii")
        data_url = f"data:audio/wav;base64,{audio_b64}"

        # 构造 OpenAI 兼容的 chat/completions 请求体
        body: dict = {
            "model": self.model,
            "messages": [
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "input_audio",
                            "input_audio": {
                                "data": data_url,
                                "format": "wav",
                            },
                        }
                    ],
                }
            ],
            "asr_options": {
                "language": self.language,
            },
        }

        try:
            resp = self.client.post("/chat/completions", json=body)
            resp.raise_for_status()
            data = resp.json()
            text = data.get("choices", [{}])[0].get("message", {}).get("content", "")
            if text:
                logger.info("ASR 识别结果: %s", text)
                return text.strip()
            logger.warning("ASR 返回空文本")
            return None
        except httpx.HTTPStatusError as e:
            logger.error("ASR HTTP 错误 %d: %s", e.response.status_code, e.response.text[:200])
            return None
        except Exception as e:
            logger.error("ASR 请求异常: %s", e)
            return None

    def close(self):
        if self._client:
            self._client.close()
            self._client = None

