"""
音频捕获 —— WASAPI Loopback 系统音频采集。

捕获电脑正在播放的声音（16kHz, mono, 16bit PCM），通过线程安全队列输出。
支持通过配置指定音频设备。
"""

import threading
import queue
import logging
from typing import Optional

import numpy as np
import sounddevice as sd

from .config import get_config

logger = logging.getLogger(__name__)


class AudioCapture:
    """系统音频采集器（WASAPI Loopback）"""

    def __init__(self, device_id: Optional[int] = None):
        cfg = get_config()
        self.sample_rate = cfg.sample_rate
        self.block_size = int(self.sample_rate * 0.1)  # 100ms 块
        self.queue: queue.Queue[Optional[np.ndarray]] = queue.Queue()
        self._stream: Optional[sd.InputStream] = None
        self._running = False
        self._device_id = device_id

    def _resolve_device(self) -> Optional[int]:
        """解析音频设备"""
        cfg = get_config()

        # 1. 显式指定的设备 ID
        if self._device_id is not None:
            return self._device_id

        # 2. 配置中的设备
        device_str = cfg.audio_device
        if device_str and device_str != "auto":
            try:
                dev_id = int(device_str)
                # 验证设备存在
                sd.query_devices(dev_id)
                logger.info("使用配置设备: [%d]", dev_id)
                return dev_id
            except (ValueError, sd.PortAudioError):
                logger.warning("配置的设备 '%s' 无效，回退到自动检测", device_str)

        # 3. 自动检测 Loopback 设备
        return self._find_loopback_device()

    def _find_loopback_device(self) -> Optional[int]:
        """查找 WASAPI Loopback 设备"""
        try:
            devices = sd.query_devices()
            for i, d in enumerate(devices):
                if d["max_input_channels"] > 0:
                    name = d["name"].lower()
                    if "loopback" in name:
                        logger.info("找到 Loopback 设备: [%d] %s", i, d["name"])
                        return int(i)
            hostapis = sd.query_hostapis()
            for i, d in enumerate(devices):
                if d["max_input_channels"] > 0:
                    api = hostapis[d["hostapi"]]
                    if "wasapi" in api["name"].lower():
                        logger.info("使用 WASAPI 输入设备: [%d] %s", i, d["name"])
                        return int(i)
        except Exception:
            pass
        return None

    def _audio_callback(self, indata: np.ndarray, frames: int, time_info, status):
        if status:
            logger.warning("音频回调状态: %s", status)
        if indata.ndim > 1:
            indata = indata.mean(axis=1)
        self.queue.put(indata.copy())

    def start(self) -> bool:
        """启动音频捕获"""
        if self._running:
            return True

        device = self._resolve_device()
        if device is None:
            logger.error("未找到可用的音频输入设备。")
            logger.error("请在设置面板中选择一个音频设备，或确保系统音频正在播放。")
            return False

        try:
            self._stream = sd.InputStream(
                device=device,
                channels=1,
                samplerate=self.sample_rate,
                callback=self._audio_callback,
                blocksize=self.block_size,
                dtype="float32",
            )
            self._stream.start()
            self._running = True
            logger.info("音频采集已启动 (device=%d, sr=%d)", device, self.sample_rate)
            return True
        except Exception as e:
            logger.error("启动音频流失败: %s", e)
            try:
                logger.warning("回退到默认输入设备...")
                self._stream = sd.InputStream(
                    channels=1,
                    samplerate=self.sample_rate,
                    callback=self._audio_callback,
                    blocksize=self.block_size,
                    dtype="float32",
                )
                self._stream.start()
                self._running = True
                logger.info("已回退到默认设备")
                return True
            except Exception as e2:
                logger.error("回退也失败: %s", e2)
                return False

    def stop(self):
        """停止音频捕获"""
        self._running = False
        if self._stream:
            try:
                self._stream.stop()
                self._stream.close()
            except Exception:
                pass
            self._stream = None
        self.queue.put(None)
        logger.info("音频采集已停止")

    def read(self, timeout: float = 0.5) -> Optional[np.ndarray]:
        """读取一个音频块（阻塞）。超时返回空数组，停止返回 None。"""
        try:
            item = self.queue.get(timeout=timeout)
            if item is None:
                return None
            return item
        except queue.Empty:
            return np.array([], dtype=np.float32)

    def read_nonblocking(self) -> Optional[np.ndarray]:
        """读取一个音频块（非阻塞）"""
        try:
            return self.queue.get_nowait()
        except queue.Empty:
            return None

